// arith_gcd_small.dice, translated by tddlog's scripts/dice2webppl.py.
// component 0 bool

var iterate = function(f, x, k) {
  return k == 0 ? x : iterate(f, f(x), k - 1);
};

var divide = function(s) {
  var b = s[0];
  var rest = s[1][0];
  var shifted = s[1][1] * 2 % 512;
  var r = Math.floor(rest / 256) % 2 == 1 ? (shifted + 1) % 512 : shifted;
  return [b, [rest * 2 % 512, b > r ? r : (r - b + 512) % 512]];
};

var round = function(s) {
  var a = s[0];
  var b = s[1];
  var m = iterate(divide, [b, [a, 0]], 9)[1][1];
  return [b, m == 0 ? b : m];
};

var model = function() {
  var a = (randomInteger(256) + 1) % 512;
  var b = (randomInteger(256) + 1) % 512;
  return iterate(round, [a, b], 13)[0] == 1;
};

Infer({method: 'enumerate'}, model);

